import numpy as np
from scipy.optimize import curve_fit
d = np.genfromtxt('/app/spectrum.csv', delimiter=',', names=True)
x = np.array(d[d.dtype.names[0]], float); y = np.array(d['intensity'], float)
def lor(x,a,x0,g):
    return a*g**2/((x-x0)**2+g**2)
def model3(x,a1,x1,g1,a2,x2,g2,a3,x3,g3,c):
    return lor(x,a1,x1,g1)+lor(x,a2,x2,g2)+lor(x,a3,x3,g3)+c
def model3lin(x,a1,x1,g1,a2,x2,g2,a3,x3,g3,c,m):
    return model3(x,a1,x1,g1,a2,x2,g2,a3,x3,g3,c)+m*(x-2000)
def model4(x,a1,x1,g1,a2,x2,g2,a3,x3,g3,a4,x4,g4,c):
    return model3(x,a1,x1,g1,a2,x2,g2,a3,x3,g3,c)+lor(x,a4,x4,g4)

p0=[12100,1346,15, 8620,1585,14, 10760,2678,20, 1100]
pg,_=curve_fit(model3,x,y,p0=p0,maxfev=300000)
print('model3 params:', np.array2string(pg,precision=3), 'rms', (y-model3(x,*pg)).std())
res = y-model3(x,*pg)
for lo in range(1100,3000,100):
    m=(x>=lo)&(x<lo+100)
    print(f'  bin {lo}-{lo+100}: resid mean={res[m].mean():8.1f} std={res[m].std():7.1f}')

try:
    pl,_=curve_fit(model3lin,x,y,p0=list(pg)+[0.0],maxfev=300000)
    print('model3+lin:', np.array2string(pl,precision=3),'rms',(y-model3lin(x,*pl)).std())
except Exception as e: print('lin fail',e)

for x4 in [1620, 2450, 3100, 1200]:
    try:
        p4,_=curve_fit(model4,x,y,p0=list(pg[:9])+[200.0,x4,60.0,pg[9]],maxfev=300000)
        print(f'model4 extra@{x4}: rms',(y-model4(x,*p4)).std(),'extra amp/g:',p4[9],p4[11])
    except Exception as e: print('m4 fail',e)

# noise estimate in flat region 1700-2400 with linear detrend
m=(x>=1700)&(x<=2400)
xx,yy=x[m],y[m]
co=np.polyfit(xx,yy,1); r=yy-np.polyval(co,xx)
print('flat-region residual std (linear detrend):', r.std())
